use crate::cards;

/// Return the reply produced by the live hopper for a wire.
/// Cards are loaded at command time so cards added after compilation work too.
pub fn reply(n: i64) -> String {
    cards::load()
        .into_iter()
        .find(|row| row.wire == n)
        .map(|row| row.reply)
        .unwrap_or_else(|| "fallthrough".to_string())
}

/// A card is served only if jab on its wire produces that card's own reply.
pub fn serves(wire: i64, expected: &str) -> bool {
    reply(wire) == expected
}

